draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw book
  ctx.fillStyle = '#964B00';
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillRect(W/2-50, H/2-75, 100, 150);
  ctx.strokeRect(W/2-50, H/2-75, 100, 150);

  // draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2+100, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+120);
  ctx.lineTo(W/2, H/2+180);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+150);
  ctx.lineTo(W/2-30, H/2+120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+150);
  ctx.lineTo(W/2+30, H/2+120);
  ctx.stroke();

  // draw speech bubble
  ctx.fillStyle = 'white';
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2+80, H/2+50, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Apply', W/2+80, H/2+50);

  // animate stick figure and book
  ctx.save();
  ctx.translate(W/2, H/2);
  ctx.rotate(Math.sin(t));
  ctx.translate(-W/2, -H/2);
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+150);
  ctx.lineTo(W/2-30+20*Math.sin(t), H/2+120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+150);
  ctx.lineTo(W/2+30+20*Math.cos(t), H/2+120);
  ctx.stroke();
  ctx.restore();

  ctx.restore();
}
